-- auto-apply
-- Hand-reviewed grammar_curriculum examples (2026-10-26).
-- The AI-written sets had correct sentences filed under 'incorrect'
-- (e.g. 아침을 먹고 버스를 탔어요, 늦지 마십시오) and wrong ones under
-- 'correct' (풀을까요, 날씨가 좋고 산책했어요, 오늘이 몇 월이에요?).
-- Each set: 12 natural examples + 3 real mistakes with the correction.
-- Idempotent: rewrites examples_json for these ids only.
update public.grammar_curriculum set examples_json = '[{"ko": "아침에 밥을 먹고 학교에 가요.", "en": "I eat breakfast and go to school in the morning.", "note": "Two actions in order", "type": "correct"}, {"ko": "커피를 마시고 일을 시작해요.", "en": "I drink coffee and then start work.", "note": "Two actions in order", "type": "correct"}, {"ko": "옷을 갈아입고 나갔어요.", "en": "I changed clothes and went out.", "note": "Two actions in order", "type": "correct"}, {"ko": "이 식당은 맛있고 싸요.", "en": "This restaurant is tasty and cheap.", "note": "Listing two qualities", "type": "correct"}, {"ko": "책을 읽고 숙제를 했어요.", "en": "I read a book and did my homework.", "note": "Two actions in order", "type": "correct"}, {"ko": "엄마는 요리하고 아빠는 설거지해요.", "en": "Mom cooks and Dad does the dishes.", "note": "Two people, two actions", "type": "correct"}, {"ko": "여행 가서 사진을 찍고 맛있는 것도 먹었어요.", "en": "On the trip I took photos and ate good food too.", "note": "Listing actions", "type": "correct"}, {"ko": "비가 오고 바람도 불어요.", "en": "It''s raining and windy too.", "note": "Listing two facts", "type": "correct"}, {"ko": "손을 씻고 드세요.", "en": "Please wash your hands and then eat.", "note": "Do A, then B", "type": "correct"}, {"ko": "제 동생은 키가 크고 착해요.", "en": "My younger sibling is tall and kind.", "note": "Listing two qualities", "type": "correct"}, {"ko": "주말에는 청소하고 쉬었어요.", "en": "On the weekend I cleaned and rested.", "note": "Listing actions", "type": "correct"}, {"ko": "이 방은 넓고 밝아요.", "en": "This room is spacious and bright.", "note": "Listing two qualities", "type": "correct"}, {"ko": "날씨가 좋고 공원에서 산책했어요.", "en": "The weather was nice, so I took a walk in the park.", "correction": "날씨가 좋아서 공원에서 산책했어요.", "note": "A reason → result needs -아/어서, not -고.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "피곤하고 일찍 자고 싶어요.", "en": "I''m tired, so I want to sleep early.", "correction": "피곤해서 일찍 자고 싶어요.", "note": "A reason → result needs -아/어서, not -고.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 친구를 만나었고 영화를 봤어요.", "en": "Yesterday I met a friend and watched a movie.", "correction": "어제 친구를 만나고 영화를 봤어요.", "note": "Tense goes on the last verb only; 만나었고 is not a form.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = 'dc46ddba-bbeb-499a-b587-558797650ab9';
update public.grammar_curriculum set examples_json = '[{"ko": "날씨는 좋지만 바람이 많이 불어요.", "en": "The weather is nice, but it''s very windy.", "note": "", "type": "correct"}, {"ko": "이 음식은 맛있지만 너무 매워요.", "en": "This food is tasty, but it''s too spicy.", "note": "", "type": "correct"}, {"ko": "한국어를 오래 공부했지만 아직 어려워요.", "en": "I''ve studied Korean for a long time, but it''s still hard.", "note": "", "type": "correct"}, {"ko": "그 일은 쉽지만 시간이 오래 걸려요.", "en": "That work is easy, but it takes a long time.", "note": "", "type": "correct"}, {"ko": "영화표는 비쌌지만 정말 재미있었어요.", "en": "The movie ticket was expensive, but it was really fun.", "note": "", "type": "correct"}, {"ko": "회사는 멀지만 월급이 좋아요.", "en": "The company is far, but the pay is good.", "note": "", "type": "correct"}, {"ko": "서울은 복잡하지만 볼 게 많아요.", "en": "Seoul is hectic, but there''s a lot to see.", "note": "", "type": "correct"}, {"ko": "그 친구는 조용하지만 재미있는 사람이에요.", "en": "That friend is quiet, but fun.", "note": "", "type": "correct"}, {"ko": "여행은 피곤했지만 좋은 경험이었어요.", "en": "The trip was tiring, but it was a good experience.", "note": "", "type": "correct"}, {"ko": "이 책은 두껍지만 금방 읽을 수 있어요.", "en": "This book is thick, but you can read it quickly.", "note": "", "type": "correct"}, {"ko": "방은 작지만 햇빛이 잘 들어와요.", "en": "The room is small, but it gets lots of sunlight.", "note": "", "type": "correct"}, {"ko": "시험은 어려웠지만 합격했어요.", "en": "The exam was hard, but I passed.", "note": "", "type": "correct"}, {"ko": "날씨가 춥지만 그래서 집에 있었어요.", "en": "It was cold, so I stayed home.", "correction": "날씨가 추워서 집에 있었어요.", "note": "-지만 shows contrast; it can''t be followed by 그래서 (so).", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "그 사람은 착하지만 좋은 사람이에요.", "en": "That person is kind, but a good person.", "correction": "그 사람은 착하고 좋은 사람이에요.", "note": "The two parts don''t contrast, so -지만 doesn''t fit; use -고.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 비가 오지만 우산이 없었어요.", "en": "It rained yesterday, but I had no umbrella.", "correction": "어제 비가 왔지만 우산이 없었어요.", "note": "Past events need the past form before -지만: 왔지만.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '34f56216-4e2e-48e6-9349-265bb855482d';
update public.grammar_curriculum set examples_json = '[{"ko": "비가 와서 우산을 가져갔어요.", "en": "It was raining, so I took an umbrella.", "note": "", "type": "correct"}, {"ko": "시간이 없어서 아침을 못 먹었어요.", "en": "I didn''t have time, so I couldn''t eat breakfast.", "note": "", "type": "correct"}, {"ko": "날씨가 좋아서 공원에 갔어요.", "en": "The weather was nice, so I went to the park.", "note": "", "type": "correct"}, {"ko": "커피가 뜨거워서 천천히 마셨어요.", "en": "The coffee was hot, so I drank it slowly.", "note": "", "type": "correct"}, {"ko": "영화가 재미있어서 끝까지 봤어요.", "en": "The movie was fun, so I watched it to the end.", "note": "", "type": "correct"}, {"ko": "길이 막혀서 늦었어요.", "en": "The traffic was bad, so I was late.", "note": "", "type": "correct"}, {"ko": "배가 고파서 간식을 먹었어요.", "en": "I was hungry, so I had a snack.", "note": "", "type": "correct"}, {"ko": "일이 많아서 퇴근을 못 했어요.", "en": "I had a lot of work, so I couldn''t leave the office.", "note": "", "type": "correct"}, {"ko": "친구가 너무 웃겨서 배가 아팠어요.", "en": "My friend was so funny my stomach hurt.", "note": "", "type": "correct"}, {"ko": "설명이 어려워서 이해를 못 했어요.", "en": "The explanation was hard, so I didn''t understand.", "note": "", "type": "correct"}, {"ko": "늦어서 죄송해요.", "en": "Sorry I''m late.", "note": "", "type": "correct"}, {"ko": "집에서 멀어서 자주 못 가요.", "en": "It''s far from home, so I can''t go often.", "note": "", "type": "correct"}, {"ko": "돈이 없어서 그 옷을 사고 싶어요.", "en": "I have no money, so I want to buy those clothes.", "correction": "돈이 없어서 그 옷을 못 사요.", "note": "The result doesn''t follow from the reason.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "비가 와서 우산을 가져가세요.", "en": "It''s raining, so take an umbrella.", "correction": "비가 오니까 우산을 가져가세요.", "note": "-아/어서 can''t be followed by a command or suggestion; use -(으)니까.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 바빴어서 전화를 못 했어요.", "en": "I was busy yesterday, so I couldn''t call.", "correction": "어제 바빠서 전화를 못 했어요.", "note": "No past tense before -아/어서: 바빠서, not 바빴어서.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '714d3f6d-8616-4d2d-8ba8-e7a2bbd9e0fe';
update public.grammar_curriculum set examples_json = '[{"ko": "비가 오면 우산을 가져가세요.", "en": "If it rains, take an umbrella.", "note": "", "type": "correct"}, {"ko": "시간이 있으면 같이 영화 봐요.", "en": "If you have time, let''s watch a movie together.", "note": "", "type": "correct"}, {"ko": "너무 매우면 물을 드세요.", "en": "If it''s too spicy, drink some water.", "note": "", "type": "correct"}, {"ko": "내일 날씨가 좋으면 공원에 갈 거예요.", "en": "If the weather is nice tomorrow, I''ll go to the park.", "note": "", "type": "correct"}, {"ko": "문제가 있으면 저한테 말해 주세요.", "en": "If there''s a problem, please tell me.", "note": "", "type": "correct"}, {"ko": "돈이 많으면 세계 여행을 하고 싶어요.", "en": "If I had a lot of money, I''d like to travel the world.", "note": "", "type": "correct"}, {"ko": "일찍 자면 아침에 덜 피곤해요.", "en": "If I sleep early, I''m less tired in the morning.", "note": "", "type": "correct"}, {"ko": "약속에 늦으면 친구가 화낼 거예요.", "en": "If I''m late, my friend will get angry.", "note": "", "type": "correct"}, {"ko": "한국어를 잘하면 드라마를 자막 없이 볼 수 있어요.", "en": "If you''re good at Korean, you can watch dramas without subtitles.", "note": "", "type": "correct"}, {"ko": "버스가 오면 타세요.", "en": "When the bus comes, get on.", "note": "", "type": "correct"}, {"ko": "피곤하면 좀 쉬어도 돼요.", "en": "If you''re tired, you can rest a bit.", "note": "", "type": "correct"}, {"ko": "이 버튼을 누르면 문이 열려요.", "en": "If you press this button, the door opens.", "note": "", "type": "correct"}, {"ko": "어제 비가 오면 집에 있었어요.", "en": "If it rained yesterday, I stayed home.", "correction": "어제 비가 와서 집에 있었어요.", "note": "-(으)면 is for conditions, not for something that already happened.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "시간이 있었으면 내일 만나요.", "en": "If you have time, let''s meet tomorrow.", "correction": "시간이 있으면 내일 만나요.", "note": "For a future condition use the plain form: 있으면.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "날씨가 좋면 산책해요.", "en": "If the weather is nice, I take a walk.", "correction": "날씨가 좋으면 산책해요.", "note": "After a final consonant use -으면: 좋으면.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = 'c2029ace-ce1a-4164-8774-cd4dba9e1f03';
update public.grammar_curriculum set examples_json = '[{"ko": "저는 아침마다 커피를 마셔요.", "en": "I drink coffee every morning.", "note": "", "type": "correct"}, {"ko": "주말마다 가족과 영화를 봐요.", "en": "Every weekend I watch movies with my family.", "note": "", "type": "correct"}, {"ko": "석 달마다 치과에 가요.", "en": "I go to the dentist every three months.", "note": "", "type": "correct"}, {"ko": "수업이 끝날 때마다 선생님께 질문해요.", "en": "Every time class ends, I ask the teacher questions.", "note": "", "type": "correct"}, {"ko": "계절마다 옷장을 정리해요.", "en": "I reorganize my closet every season.", "note": "", "type": "correct"}, {"ko": "비가 올 때마다 무릎이 아파요.", "en": "My knee hurts every time it rains.", "note": "", "type": "correct"}, {"ko": "생일마다 친구들이 파티를 해 줘요.", "en": "My friends throw me a party every birthday.", "note": "", "type": "correct"}, {"ko": "출근할 때마다 지하철을 타요.", "en": "I take the subway every time I go to work.", "note": "", "type": "correct"}, {"ko": "손님이 올 때마다 집을 청소해요.", "en": "I clean the house every time guests come.", "note": "", "type": "correct"}, {"ko": "이 노래를 들을 때마다 눈물이 나요.", "en": "I tear up every time I hear this song.", "note": "", "type": "correct"}, {"ko": "사람마다 생각이 달라요.", "en": "Everyone thinks differently.", "note": "", "type": "correct"}, {"ko": "버스가 10분마다 와요.", "en": "The bus comes every 10 minutes.", "note": "", "type": "correct"}, {"ko": "매일마다 숙제를 해요.", "en": "I do homework every day.", "correction": "매일 숙제를 해요.", "note": "매일 already means ''every day''; don''t add 마다.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "마다 저는 책을 읽어요.", "en": "I read a book every day.", "correction": "저는 날마다 책을 읽어요.", "note": "마다 attaches to a noun: 날마다.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "주말을마다 등산을 해요.", "en": "I go hiking every weekend.", "correction": "주말마다 등산을 해요.", "note": "No particle between the noun and 마다.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '27531baa-eec6-4202-a4b4-4b9817953242';
update public.grammar_curriculum set examples_json = '[{"ko": "매일 운동하는 것이 건강에 좋아요.", "en": "Exercising every day is good for your health.", "note": "", "type": "correct"}, {"ko": "저는 한국 음식을 먹는 것을 좋아해요.", "en": "I like eating Korean food.", "note": "", "type": "correct"}, {"ko": "새로운 일을 시작하는 것이 조금 무서워요.", "en": "Starting a new job is a little scary.", "note": "", "type": "correct"}, {"ko": "친구들을 만나는 것이 제일 즐거워요.", "en": "Meeting friends is the most fun.", "note": "", "type": "correct"}, {"ko": "한국어를 배우는 것은 재미있어요.", "en": "Learning Korean is fun.", "note": "", "type": "correct"}, {"ko": "오늘 회의가 있는 것을 깜빡했어요.", "en": "I forgot that there was a meeting today.", "note": "", "type": "correct"}, {"ko": "제 취미는 사진을 찍는 거예요.", "en": "My hobby is taking photos.", "note": "", "type": "correct"}, {"ko": "밤에 공부하는 것이 더 편해요.", "en": "Studying at night is more comfortable for me.", "note": "", "type": "correct"}, {"ko": "혼자 여행하는 것을 추천해요.", "en": "I recommend traveling alone.", "note": "", "type": "correct"}, {"ko": "집에서 일하는 것에는 장점이 많아요.", "en": "Working from home has many advantages.", "note": "", "type": "correct"}, {"ko": "친구와 이야기하는 것이 스트레스 해소에 좋아요.", "en": "Talking with friends is good for relieving stress.", "note": "", "type": "correct"}, {"ko": "가장 어려운 건 발음하는 거예요.", "en": "The hardest thing is pronunciation.", "note": "", "type": "correct"}, {"ko": "한국에 가는 것를 원해요.", "en": "I want to go to Korea.", "correction": "한국에 가는 것을 원해요.", "note": "것 ends in a consonant, so the object marker is 을.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "저는 노래하다 것을 좋아해요.", "en": "I like singing.", "correction": "저는 노래하는 것을 좋아해요.", "note": "Verbs take -는 before 것: 노래하는 것.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 친구를 만나는 것이 재미있었어요.", "en": "Meeting my friend yesterday was fun.", "correction": "어제 친구를 만난 것이 재미있었어요.", "note": "For a finished past event use -(으)ㄴ 것: 만난 것.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '56218069-02e8-4664-b85f-2dc7ff2c36ff';
update public.grammar_curriculum set examples_json = '[{"ko": "일찍 일어나려고 알람을 여러 개 맞췄어요.", "en": "I set several alarms to wake up early.", "note": "", "type": "correct"}, {"ko": "건강해지려고 매일 운동해요.", "en": "I exercise every day to get healthier.", "note": "", "type": "correct"}, {"ko": "시험에 합격하려고 열심히 공부했어요.", "en": "I studied hard to pass the exam.", "note": "", "type": "correct"}, {"ko": "한국어를 배우려고 한국 드라마를 자주 봐요.", "en": "I often watch Korean dramas to learn Korean.", "note": "", "type": "correct"}, {"ko": "돈을 모으려고 아르바이트를 시작했어요.", "en": "I started a part-time job to save money.", "note": "", "type": "correct"}, {"ko": "요리를 배우려고 요리 수업에 등록했어요.", "en": "I signed up for a cooking class to learn to cook.", "note": "", "type": "correct"}, {"ko": "버스를 타려고 정류장에서 기다리고 있어요.", "en": "I''m waiting at the stop to catch the bus.", "note": "", "type": "correct"}, {"ko": "잠을 깨려고 커피를 마셨어요.", "en": "I drank coffee to wake myself up.", "note": "", "type": "correct"}, {"ko": "시간을 아끼려고 택시를 탔어요.", "en": "I took a taxi to save time.", "note": "", "type": "correct"}, {"ko": "친구에게 주려고 케이크를 샀어요.", "en": "I bought a cake to give to my friend.", "note": "", "type": "correct"}, {"ko": "살을 빼려고 저녁을 조금만 먹어요.", "en": "I eat only a little dinner to lose weight.", "note": "", "type": "correct"}, {"ko": "부모님을 뵈려고 고향에 다녀왔어요.", "en": "I went back to my hometown to see my parents.", "note": "", "type": "correct"}, {"ko": "날씨가 좋으려고 우산을 안 가져왔어요.", "en": "I didn''t bring an umbrella so the weather would be nice.", "correction": "날씨가 좋을 것 같아서 우산을 안 가져왔어요.", "note": "-(으)려고 takes an action you intend, not an adjective.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "동생이 공부하려고 제가 조용히 했어요.", "en": "I kept quiet so my sibling could study.", "correction": "동생이 공부할 수 있게 제가 조용히 했어요.", "note": "With -(으)려고 the same person does both actions; use -게 for someone else.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "한국어를 배우려고 한국에 가세요.", "en": "Go to Korea to learn Korean.", "correction": "한국어를 배우려면 한국에 가세요.", "note": "-(으)려고 can''t be followed by a command; use -(으)려면.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = 'ff77bd87-68d4-44bf-9265-4acd42e09169';
update public.grammar_curriculum set examples_json = '[{"ko": "저는 학생이에요.", "en": "I''m a student.", "note": "은/는 introduces the topic", "type": "correct"}, {"ko": "오늘은 날씨가 맑아요.", "en": "Today, the weather is clear.", "note": "Topic 오늘은, subject 날씨가", "type": "correct"}, {"ko": "누가 왔어요?", "en": "Who came?", "note": "Question words take 이/가", "type": "correct"}, {"ko": "제 형이 의사예요.", "en": "It''s my older brother who is a doctor.", "note": "이/가 points to who", "type": "correct"}, {"ko": "이 음식은 맛있어요.", "en": "This food is tasty.", "note": "", "type": "correct"}, {"ko": "뭐가 문제예요?", "en": "What''s the problem?", "note": "Question words take 이/가", "type": "correct"}, {"ko": "커피는 좋아하지만 차는 안 좋아해요.", "en": "I like coffee, but not tea.", "note": "은/는 for contrast", "type": "correct"}, {"ko": "어느 학생이 1등이에요?", "en": "Which student came first?", "note": "", "type": "correct"}, {"ko": "저희 회사는 IT 회사예요.", "en": "Our company is an IT company.", "note": "", "type": "correct"}, {"ko": "이 책이 누구 거예요?", "en": "Whose is this book?", "note": "", "type": "correct"}, {"ko": "한국 음식은 건강에 좋아요.", "en": "Korean food is good for your health.", "note": "General statement → 은/는", "type": "correct"}, {"ko": "지금 몇 시예요?", "en": "What time is it now?", "note": "", "type": "correct"}, {"ko": "누구는 왔어요?", "en": "Who came?", "correction": "누가 왔어요?", "note": "Question words like 누구 take 이/가 (누가).", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "그 사람이는 선생님이에요.", "en": "That person is a teacher.", "correction": "그 사람은 선생님이에요.", "note": "Use only one particle: 사람은.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "무엇은 문제예요?", "en": "What''s the problem?", "correction": "뭐가 문제예요?", "note": "Question words take 이/가, not 은/는.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = 'cfb931aa-4d32-4d55-b105-49ab94afd95b';
update public.grammar_curriculum set examples_json = '[{"ko": "저는 매일 아침 커피를 마셔요.", "en": "I drink coffee every morning.", "note": "", "type": "correct"}, {"ko": "언니가 책을 읽고 있어요.", "en": "My older sister is reading a book.", "note": "", "type": "correct"}, {"ko": "아이들이 공원에서 공을 차요.", "en": "The children are kicking a ball in the park.", "note": "", "type": "correct"}, {"ko": "엄마가 저녁을 준비하고 있어요.", "en": "Mom is preparing dinner.", "note": "", "type": "correct"}, {"ko": "학교에서 친구를 만났어요.", "en": "I met a friend at school.", "note": "", "type": "correct"}, {"ko": "동생이 숙제를 다 했어요?", "en": "Did your younger sibling finish their homework?", "note": "", "type": "correct"}, {"ko": "저는 영화를 좋아해요.", "en": "I like movies.", "note": "", "type": "correct"}, {"ko": "그 사람은 새 차를 샀어요.", "en": "That person bought a new car.", "note": "", "type": "correct"}, {"ko": "오늘 저녁에 뭘 먹을 거예요?", "en": "What are you going to eat tonight?", "note": "", "type": "correct"}, {"ko": "형이 짐을 들어 줬어요.", "en": "My older brother carried the bags for me.", "note": "", "type": "correct"}, {"ko": "저는 한국어를 배우고 싶어요.", "en": "I want to learn Korean.", "note": "", "type": "correct"}, {"ko": "주말에 할머니를 뵈었어요.", "en": "I visited my grandmother on the weekend.", "note": "", "type": "correct"}, {"ko": "저는 사과을 좋아해요.", "en": "I like apples.", "correction": "저는 사과를 좋아해요.", "note": "After a vowel use 를: 사과를.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "우리는 친구에게를 도와줬어요.", "en": "We helped our friend.", "correction": "우리는 친구를 도와줬어요.", "note": "Don''t stack particles; 돕다 takes the object marker.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "저는 책를 읽어요.", "en": "I read a book.", "correction": "저는 책을 읽어요.", "note": "After a consonant use 을: 책을.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '9232bcc3-9711-47dc-b90c-921465f45341';
update public.grammar_curriculum set examples_json = '[{"ko": "저는 매일 학교에 가요.", "en": "I go to school every day.", "note": "에 = destination", "type": "correct"}, {"ko": "학교에서 친구들을 만나요.", "en": "I meet my friends at school.", "note": "에서 = where an action happens", "type": "correct"}, {"ko": "카페에 들어갔어요.", "en": "I went into the café.", "note": "", "type": "correct"}, {"ko": "카페에서 커피를 마셔요.", "en": "I drink coffee at the café.", "note": "", "type": "correct"}, {"ko": "집에 돌아왔어요.", "en": "I came back home.", "note": "", "type": "correct"}, {"ko": "집에서 숙제를 해요.", "en": "I do my homework at home.", "note": "", "type": "correct"}, {"ko": "병원에 가야 해요.", "en": "I need to go to the hospital.", "note": "", "type": "correct"}, {"ko": "병원에서 의사를 만났어요.", "en": "I saw a doctor at the hospital.", "note": "", "type": "correct"}, {"ko": "다음 주에 서울에 출장을 가요.", "en": "I''m going to Seoul on a business trip next week.", "note": "", "type": "correct"}, {"ko": "서울에서 맛있는 음식을 먹었어요.", "en": "I ate great food in Seoul.", "note": "", "type": "correct"}, {"ko": "책상 위에 책이 있어요.", "en": "There''s a book on the desk.", "note": "에 with 있다 = location of existence", "type": "correct"}, {"ko": "도서관에서 공부하는 학생이 많아요.", "en": "Many students study at the library.", "note": "", "type": "correct"}, {"ko": "공원에 산책했어요.", "en": "I took a walk in the park.", "correction": "공원에서 산책했어요.", "note": "An action happening in a place takes 에서.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "저는 매일 학교에서 가요.", "en": "I go to school every day.", "correction": "저는 매일 학교에 가요.", "note": "Moving toward a place takes 에: 학교에 가요.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "방에서 고양이가 있어요.", "en": "There''s a cat in the room.", "correction": "방에 고양이가 있어요.", "note": "있다/없다 take 에 for where something is.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '9b2d2e6d-ad0e-46e6-a966-777061b67ec9';
update public.grammar_curriculum set examples_json = '[{"ko": "저도 커피를 마셔요.", "en": "I drink coffee too.", "note": "", "type": "correct"}, {"ko": "오늘도 날씨가 좋아요.", "en": "The weather is nice today too.", "note": "", "type": "correct"}, {"ko": "엄마도 영화를 좋아해요.", "en": "Mom likes movies too.", "note": "", "type": "correct"}, {"ko": "저는 한국어도 배워요.", "en": "I''m learning Korean too.", "note": "", "type": "correct"}, {"ko": "학교도 집에서 멀어요.", "en": "School is far from home too.", "note": "", "type": "correct"}, {"ko": "언니도 회사에 있어요.", "en": "My older sister is at the office too.", "note": "", "type": "correct"}, {"ko": "저녁도 같이 먹을래요?", "en": "Do you want to have dinner together too?", "note": "", "type": "correct"}, {"ko": "방학도 곧 시작해요.", "en": "Vacation starts soon too.", "note": "", "type": "correct"}, {"ko": "한국도 여름에는 더워요.", "en": "Korea is hot in summer too.", "note": "", "type": "correct"}, {"ko": "아빠도 피자를 드셨어요.", "en": "Dad had pizza too.", "note": "", "type": "correct"}, {"ko": "내일도 일이 있어요.", "en": "I have work tomorrow too.", "note": "", "type": "correct"}, {"ko": "학교에도 친구가 있어요.", "en": "I have friends at school too.", "note": "도 can follow 에", "type": "correct"}, {"ko": "도 저는 한국어를 배워요.", "en": "I''m learning Korean too.", "correction": "저도 한국어를 배워요.", "note": "도 attaches after a noun.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "엄마가도 밥을 해요.", "en": "Mom cooks too.", "correction": "엄마도 밥을 해요.", "note": "도 replaces 이/가; don''t stack them.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "저는 커피를도 좋아해요.", "en": "I like coffee too.", "correction": "저는 커피도 좋아해요.", "note": "도 replaces 을/를; don''t stack them.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '5782158c-3e16-4f94-aa3c-b8ea54696317';
update public.grammar_curriculum set examples_json = '[{"ko": "저는 커피를 마시고 싶어요.", "en": "I want to drink coffee.", "note": "", "type": "correct"}, {"ko": "오늘은 영화를 보고 싶어.", "en": "I want to watch a movie today.", "note": "Casual", "type": "correct"}, {"ko": "한국에 가고 싶습니다.", "en": "I want to go to Korea.", "note": "Formal", "type": "correct"}, {"ko": "새 옷을 사고 싶어요.", "en": "I want to buy new clothes.", "note": "", "type": "correct"}, {"ko": "내일은 좀 쉬고 싶어.", "en": "I want to rest a bit tomorrow.", "note": "Casual", "type": "correct"}, {"ko": "보고 싶어요.", "en": "I miss you.", "note": "Lit. ''I want to see you''", "type": "correct"}, {"ko": "뭐 먹고 싶어요?", "en": "What do you want to eat?", "note": "", "type": "correct"}, {"ko": "지금 자고 싶어요.", "en": "I want to sleep now.", "note": "", "type": "correct"}, {"ko": "한국어를 잘하고 싶어요.", "en": "I want to be good at Korean.", "note": "", "type": "correct"}, {"ko": "주말에 산에 가고 싶어요.", "en": "I want to go to the mountains this weekend.", "note": "", "type": "correct"}, {"ko": "돈을 더 많이 벌고 싶어요.", "en": "I want to earn more money.", "note": "", "type": "correct"}, {"ko": "아이스크림 사 먹고 싶어.", "en": "I want to buy some ice cream.", "note": "Casual", "type": "correct"}, {"ko": "민수 씨는 한국에 가고 싶어요.", "en": "Minsu wants to go to Korea.", "correction": "민수 씨는 한국에 가고 싶어해요.", "note": "For someone else''s wish use -고 싶어하다.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "저는 공부해고 싶어요.", "en": "I want to study.", "correction": "저는 공부하고 싶어요.", "note": "Attach -고 싶다 to the verb stem: 공부하고.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 영화를 보고 싶었다요.", "en": "I wanted to watch a movie yesterday.", "correction": "어제 영화를 보고 싶었어요.", "note": "Past polite form is 싶었어요.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '2ab2910d-4952-4d1e-8f17-cd427708e6ee';
update public.grammar_curriculum set examples_json = '[{"ko": "지금 밥 먹을까요?", "en": "Shall we eat now?", "note": "", "type": "correct"}, {"ko": "오늘 영화 볼까요?", "en": "Shall we watch a movie today?", "note": "", "type": "correct"}, {"ko": "내일 공원에 갈까요?", "en": "Shall we go to the park tomorrow?", "note": "", "type": "correct"}, {"ko": "커피 한잔할까요?", "en": "Shall we have a cup of coffee?", "note": "", "type": "correct"}, {"ko": "창문 좀 열까요?", "en": "Shall I open the window?", "note": "Offering to do something", "type": "correct"}, {"ko": "회의를 내일 할까요?", "en": "Shall we have the meeting tomorrow?", "note": "", "type": "correct"}, {"ko": "조금 더 기다릴까요?", "en": "Shall we wait a bit longer?", "note": "", "type": "correct"}, {"ko": "점심에 중국 음식 먹을까요?", "en": "Shall we have Chinese food for lunch?", "note": "", "type": "correct"}, {"ko": "이 문제부터 풀까요?", "en": "Shall we solve this problem first?", "note": "", "type": "correct"}, {"ko": "주말에 같이 여행 갈까요?", "en": "Shall we take a trip together this weekend?", "note": "", "type": "correct"}, {"ko": "이제 그만할까요?", "en": "Shall we stop now?", "note": "", "type": "correct"}, {"ko": "비가 오는데 택시 탈까요?", "en": "It''s raining — shall we take a taxi?", "note": "", "type": "correct"}, {"ko": "이 문제를 먼저 풀을까요?", "en": "Shall we solve this problem first?", "correction": "이 문제를 먼저 풀까요?", "note": "ㄹ-stem verbs take -까요 directly: 풀까요.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "공원에 간을까요?", "en": "Shall we go to the park?", "correction": "공원에 갈까요?", "note": "After a vowel stem use -ㄹ까요: 갈까요.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 같이 영화 볼까요?", "en": "Shall we watch a movie yesterday?", "correction": "내일 같이 영화 볼까요?", "note": "Suggestions are about now or the future, not the past.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = 'f4539702-dddb-4119-abff-49f66eb6447a';
update public.grammar_curriculum set examples_json = '[{"ko": "늦지 마세요.", "en": "Don''t be late.", "note": "", "type": "correct"}, {"ko": "물을 낭비하지 마세요.", "en": "Don''t waste water.", "note": "", "type": "correct"}, {"ko": "그 음식 먹지 마세요. 상했어요.", "en": "Don''t eat that food. It''s gone bad.", "note": "", "type": "correct"}, {"ko": "수업 시간에 자지 마세요.", "en": "Don''t sleep in class.", "note": "", "type": "correct"}, {"ko": "창문을 열지 마세요. 추워요.", "en": "Don''t open the window. It''s cold.", "note": "", "type": "correct"}, {"ko": "수업 중에 휴대폰을 쓰지 마세요.", "en": "Don''t use your phone during class.", "note": "", "type": "correct"}, {"ko": "지하철에서 크게 통화하지 마세요.", "en": "Don''t talk loudly on the phone on the subway.", "note": "", "type": "correct"}, {"ko": "그쪽으로 가지 마세요. 위험해요.", "en": "Don''t go that way. It''s dangerous.", "note": "", "type": "correct"}, {"ko": "여기서 담배 피우지 마세요.", "en": "Don''t smoke here.", "note": "", "type": "correct"}, {"ko": "너무 걱정하지 마세요.", "en": "Don''t worry too much.", "note": "", "type": "correct"}, {"ko": "과식하지 마세요.", "en": "Don''t overeat.", "note": "", "type": "correct"}, {"ko": "비가 오니까 밖에 나가지 마세요.", "en": "It''s raining, so don''t go outside.", "note": "", "type": "correct"}, {"ko": "늦지 말으세요.", "en": "Don''t be late.", "correction": "늦지 마세요.", "note": "말다 drops its ㄹ here: 마세요.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "떠들지 마요세요.", "en": "Don''t make noise.", "correction": "떠들지 마세요.", "note": "The form is just 마세요.", "error_type": "GRAMMAR", "type": "incorrect"}, {"ko": "어제 늦지 마세요.", "en": "Don''t be late yesterday.", "correction": "내일 늦지 마세요.", "note": "A command can''t be about the past.", "error_type": "GRAMMAR", "type": "incorrect"}]', updated_at = now() where id = '4e499952-0e9e-4026-b1f1-7c93ea4f2ca4';
